-- Testing only. Schedule the remaining 25 approved-host candidate discovery sources every six hours.
-- These run discovery only: no auto-approval or publication.
select cron.schedule('jd-ca-web-official-testing','0 */6 * * *', $$select net.http_post(url:='https://gfoyzlbehikcxfluznvq.supabase.co/functions/v1/jd-ca-web-candidate-stage',headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(select token from public.ca_job_auth where id=1)),body:='{"dryRun":false,"sourceKeys":["AIR_NEWS","DRDO","ECI","ISRO","MOSPI"],"maxArticles":3}'::jsonb,timeout_milliseconds:=120000);$$) as official_job;
